import math


def merge_intervals(intervals):
    if not isinstance(intervals, list) or not intervals:
        raise ValueError("intervals must be a non-empty list")

    validated = []
    for interval in intervals:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError("each interval must be a 2-item tuple")

        start, end = interval
        for value in (start, end):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("interval values must be numeric")
            if isinstance(value, float) and not math.isfinite(value):
                raise ValueError("interval values must be finite")

        if start > end:
            raise ValueError("interval start cannot exceed interval end")
        validated.append((start, end))

    ordered = sorted(validated, key=lambda interval: interval[0])
    merged = [ordered[0]]
    for start, end in ordered[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged

